"""Flask task-management API backed by a JSON flat file."""

from __future__ import annotations

import base64
import binascii
import hashlib
import hmac
import json
import os
import time
from datetime import datetime, timedelta, timezone
from functools import wraps
from pathlib import Path
from threading import Lock

from flask import Flask, g, jsonify, request
from werkzeug.security import check_password_hash, generate_password_hash


app = Flask(__name__)
app.config.update(
    JWT_SECRET_KEY=os.environ.get("JWT_SECRET_KEY", "development-secret-change-me"),
    JWT_EXPIRATION_SECONDS=3600,
)

# Kept as a module setting so deployments and tests can select their data file.
DATABASE = os.environ.get("TASKS_FILE", "tasks.json")
_storage_lock = Lock()


def _empty_store() -> dict:
    return {"next_id": 1, "next_user_id": 1, "tasks": [], "users": []}


def _migrate_store(store: dict) -> bool:
    """Apply additive schema changes while retaining all existing records."""
    changed = False
    if "next_user_id" not in store:
        store["next_user_id"] = 1
        changed = True
    if "users" not in store:
        store["users"] = []
        changed = True
    for task in store.get("tasks", []):
        if "owner_id" not in task:
            task["owner_id"] = None
            changed = True
    return changed


def init_db() -> None:
    """Initialize the flat-file schema and migrate older stores in place."""
    path = Path(DATABASE)
    with _storage_lock:
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists():
            _write_store(_empty_store())
            return
        store = _read_store()
        if _migrate_store(store):
            _write_store(store)


def _read_store() -> dict:
    path = Path(DATABASE)
    if not path.exists():
        return _empty_store()
    with path.open(encoding="utf-8") as data_file:
        return json.load(data_file)


def _write_store(store: dict) -> None:
    path = Path(DATABASE)
    temporary_path = path.with_name(f".{path.name}.tmp")
    with temporary_path.open("w", encoding="utf-8") as data_file:
        json.dump(store, data_file, indent=2)
        data_file.write("\n")
    os.replace(temporary_path, path)


def create_user(username: str, password: str) -> dict | None:
    password_hash = generate_password_hash(password, method="scrypt")
    with _storage_lock:
        store = _read_store()
        if any(user["username"] == username for user in store["users"]):
            return None
        user = {
            "id": store["next_user_id"],
            "username": username,
            "password_hash": password_hash,
        }
        store["next_user_id"] += 1
        store["users"].append(user)
        _write_store(store)
        return user.copy()


def get_user_by_username(username: str) -> dict | None:
    with _storage_lock:
        for user in _read_store()["users"]:
            if user["username"] == username:
                return user.copy()
    return None


def get_user(user_id: int) -> dict | None:
    with _storage_lock:
        for user in _read_store()["users"]:
            if user["id"] == user_id:
                return user.copy()
    return None


def create_task(title: str, owner_id: int) -> dict:
    with _storage_lock:
        store = _read_store()
        task = {
            "id": store["next_id"],
            "title": title,
            "status": "pending",
            "created_at": datetime.now(timezone.utc).isoformat(),
            "owner_id": owner_id,
        }
        store["next_id"] += 1
        store["tasks"].append(task)
        _write_store(store)
        return task.copy()


def get_tasks(owner_id: int) -> list[dict]:
    with _storage_lock:
        tasks = _read_store()["tasks"]
        owned_tasks = (task.copy() for task in tasks if task.get("owner_id") == owner_id)
        return sorted(owned_tasks, key=lambda task: task["created_at"], reverse=True)


def get_task(task_id: int, owner_id: int) -> dict | None:
    with _storage_lock:
        for task in _read_store()["tasks"]:
            if task["id"] == task_id and task.get("owner_id") == owner_id:
                return task.copy()
    return None


def update_task(
    task_id: int, owner_id: int, title: str | None = None, status: str | None = None
) -> dict | None:
    with _storage_lock:
        store = _read_store()
        for task in store["tasks"]:
            if task["id"] != task_id or task.get("owner_id") != owner_id:
                continue
            if title is not None:
                task["title"] = title
            if status is not None:
                task["status"] = status
            _write_store(store)
            return task.copy()
    return None


def _base64url_encode(value: bytes) -> str:
    return base64.urlsafe_b64encode(value).rstrip(b"=").decode("ascii")


def _base64url_decode(value: str) -> bytes:
    return base64.urlsafe_b64decode(value + "=" * (-len(value) % 4))


def create_token(user_id: int) -> str:
    now = datetime.now(timezone.utc)
    header = {"alg": "HS256", "typ": "JWT"}
    payload = {
        "sub": user_id,
        "iat": int(now.timestamp()),
        "exp": int((now + timedelta(seconds=app.config["JWT_EXPIRATION_SECONDS"])).timestamp()),
    }
    encoded_header = _base64url_encode(json.dumps(header, separators=(",", ":")).encode())
    encoded_payload = _base64url_encode(json.dumps(payload, separators=(",", ":")).encode())
    signing_input = f"{encoded_header}.{encoded_payload}"
    signature = hmac.new(
        app.config["JWT_SECRET_KEY"].encode(), signing_input.encode(), hashlib.sha256
    ).digest()
    return f"{signing_input}.{_base64url_encode(signature)}"


def decode_token(token: str) -> int | None:
    try:
        encoded_header, encoded_payload, encoded_signature = token.split(".")
        header = json.loads(_base64url_decode(encoded_header))
        payload = json.loads(_base64url_decode(encoded_payload))
        supplied_signature = _base64url_decode(encoded_signature)
    except (ValueError, TypeError, json.JSONDecodeError, UnicodeDecodeError, binascii.Error):
        return None

    if header != {"alg": "HS256", "typ": "JWT"}:
        return None
    signing_input = f"{encoded_header}.{encoded_payload}"
    expected_signature = hmac.new(
        app.config["JWT_SECRET_KEY"].encode(), signing_input.encode(), hashlib.sha256
    ).digest()
    if not hmac.compare_digest(supplied_signature, expected_signature):
        return None

    user_id = payload.get("sub")
    expires_at = payload.get("exp")
    if (
        not isinstance(user_id, int)
        or isinstance(user_id, bool)
        or not isinstance(expires_at, int)
        or expires_at <= int(time.time())
    ):
        return None
    return user_id


def jwt_required(view):
    @wraps(view)
    def authenticated_view(*args, **kwargs):
        authorization = request.headers.get("Authorization", "")
        scheme, separator, token = authorization.partition(" ")
        if separator != " " or scheme.lower() != "bearer" or not token:
            return jsonify({"error": "authentication required"}), 401
        user_id = decode_token(token)
        user = get_user(user_id) if user_id is not None else None
        if user is None:
            return jsonify({"error": "invalid or expired token"}), 401
        g.current_user = user
        return view(*args, **kwargs)

    return authenticated_view


def _credentials() -> tuple[str, str] | None:
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return None
    username = data.get("username")
    password = data.get("password")
    if not isinstance(username, str) or not username.strip() or not isinstance(password, str) or not password:
        return None
    return username.strip(), password


@app.post("/auth/register")
def register():
    credentials = _credentials()
    if credentials is None:
        return jsonify({"error": "username and password are required"}), 400
    user = create_user(*credentials)
    if user is None:
        return jsonify({"error": "username already exists"}), 409
    return jsonify({"id": user["id"], "username": user["username"]}), 201


@app.post("/auth/login")
def login():
    credentials = _credentials()
    if credentials is None:
        return jsonify({"error": "username and password are required"}), 400
    username, password = credentials
    user = get_user_by_username(username)
    if user is None or not check_password_hash(user["password_hash"], password):
        return jsonify({"error": "invalid credentials"}), 401
    return jsonify({"token": create_token(user["id"])})


@app.get("/tasks")
@jwt_required
def list_tasks():
    return jsonify(get_tasks(g.current_user["id"]))


@app.post("/tasks")
@jwt_required
def add_task():
    data = request.get_json(silent=True)
    if not isinstance(data, dict) or not isinstance(data.get("title"), str) or not data["title"].strip():
        return jsonify({"error": "title is required"}), 400
    return jsonify(create_task(data["title"].strip(), g.current_user["id"])), 201


@app.get("/tasks/<int:task_id>")
@jwt_required
def show_task(task_id: int):
    task = get_task(task_id, g.current_user["id"])
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


@app.put("/tasks/<int:task_id>")
@jwt_required
def edit_task(task_id: int):
    if get_task(task_id, g.current_user["id"]) is None:
        return jsonify({"error": "task not found"}), 404

    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "JSON object is required"}), 400
    if "title" in data and (not isinstance(data["title"], str) or not data["title"].strip()):
        return jsonify({"error": "title must be a non-empty string"}), 400
    if "status" in data and not isinstance(data["status"], str):
        return jsonify({"error": "status must be a string"}), 400

    title = data["title"].strip() if "title" in data else None
    task = update_task(
        task_id, g.current_user["id"], title=title, status=data.get("status")
    )
    return jsonify(task)


init_db()


if __name__ == "__main__":
    app.run(debug=True)

import json

import pytest
from werkzeug.security import check_password_hash

import app as task_app


@pytest.fixture
def client(tmp_path, monkeypatch):
    monkeypatch.setattr(task_app, "DATABASE", str(tmp_path / "tasks.json"))
    task_app.app.config.update(
        TESTING=True,
        JWT_SECRET_KEY="test-secret",
        JWT_EXPIRATION_SECONDS=3600,
    )
    task_app.init_db()
    return task_app.app.test_client()


def register(client, username="alice", password="correct horse battery staple"):
    return client.post("/auth/register", json={"username": username, "password": password})


def auth_headers(client, username="alice", password="correct horse battery staple"):
    register(client, username, password)
    response = client.post("/auth/login", json={"username": username, "password": password})
    return {"Authorization": f"Bearer {response.get_json()['token']}"}


def test_storage_is_initialized_with_user_schema(tmp_path, monkeypatch):
    data_file = tmp_path / "data" / "tasks.json"
    monkeypatch.setattr(task_app, "DATABASE", str(data_file))

    task_app.init_db()

    assert json.loads(data_file.read_text()) == {
        "next_id": 1,
        "next_user_id": 1,
        "tasks": [],
        "users": [],
    }


def test_existing_storage_is_migrated_without_data_loss(tmp_path, monkeypatch):
    data_file = tmp_path / "tasks.json"
    original_task = {
        "id": 1,
        "title": "Legacy task",
        "status": "pending",
        "created_at": "2026-01-01T00:00:00+00:00",
    }
    data_file.write_text(json.dumps({"next_id": 2, "tasks": [original_task]}))
    monkeypatch.setattr(task_app, "DATABASE", str(data_file))

    task_app.init_db()

    store = json.loads(data_file.read_text())
    assert store["next_id"] == 2
    assert store["next_user_id"] == 1
    assert store["users"] == []
    assert store["tasks"] == [{**original_task, "owner_id": None}]


def test_register_creates_user_with_hashed_password(client):
    response = register(client, password="secret-password")

    assert response.status_code == 201
    assert response.get_json() == {"id": 1, "username": "alice"}
    user = task_app.get_user_by_username("alice")
    assert user["password_hash"] != "secret-password"
    assert check_password_hash(user["password_hash"], "secret-password")


def test_duplicate_username_is_rejected(client):
    assert register(client).status_code == 201

    response = register(client, password="different password")

    assert response.status_code == 409
    assert response.get_json() == {"error": "username already exists"}


@pytest.mark.parametrize(
    "body",
    [{}, {"username": "", "password": "secret"}, {"username": "alice", "password": ""}],
)
def test_register_requires_username_and_password(client, body):
    response = client.post("/auth/register", json=body)

    assert response.status_code == 400


def test_login_returns_token_accepted_by_api(client):
    register(client, password="secret-password")

    response = client.post(
        "/auth/login", json={"username": "alice", "password": "secret-password"}
    )

    assert response.status_code == 200
    token = response.get_json()["token"]
    assert token.count(".") == 2
    assert client.get("/tasks", headers={"Authorization": f"Bearer {token}"}).status_code == 200


@pytest.mark.parametrize(
    "body",
    [
        {"username": "missing", "password": "password"},
        {"username": "alice", "password": "wrong"},
    ],
)
def test_login_rejects_invalid_credentials(client, body):
    register(client)

    response = client.post("/auth/login", json=body)

    assert response.status_code == 401
    assert response.get_json() == {"error": "invalid credentials"}


@pytest.mark.parametrize(
    "headers",
    [
        {},
        {"Authorization": "Basic credentials"},
        {"Authorization": "Bearer invalid-token"},
        {"Authorization": "Bearer bad.token.value"},
    ],
)
def test_tasks_require_valid_jwt(client, headers):
    response = client.get("/tasks", headers=headers)

    assert response.status_code == 401


def test_expired_token_is_rejected(client):
    register(client)
    task_app.app.config["JWT_EXPIRATION_SECONDS"] = -1
    token = task_app.create_token(1)

    response = client.get("/tasks", headers={"Authorization": f"Bearer {token}"})

    assert response.status_code == 401


def test_create_and_get_task(client):
    headers = auth_headers(client)
    response = client.post("/tasks", json={"title": "Write tests"}, headers=headers)

    assert response.status_code == 201
    task = response.get_json()
    assert task["id"] == 1
    assert task["title"] == "Write tests"
    assert task["status"] == "pending"
    assert task["owner_id"] == 1
    assert task["created_at"]
    assert client.get("/tasks/1", headers=headers).get_json() == task


@pytest.mark.parametrize("body", [{}, {"title": ""}, {"title": "   "}, {"title": 12}])
def test_create_requires_title(client, body):
    response = client.post("/tasks", json=body, headers=auth_headers(client))

    assert response.status_code == 400
    assert response.get_json() == {"error": "title is required"}


def test_list_tasks_newest_first(client, monkeypatch):
    headers = auth_headers(client)
    timestamps = iter([
        "2026-01-01T00:00:00+00:00",
        "2026-01-02T00:00:00+00:00",
    ])

    class Clock:
        @staticmethod
        def now(_timezone):
            return type("Moment", (), {"isoformat": lambda self: next(timestamps)})()

    monkeypatch.setattr(task_app, "datetime", Clock)
    client.post("/tasks", json={"title": "Older"}, headers=headers)
    client.post("/tasks", json={"title": "Newer"}, headers=headers)

    response = client.get("/tasks", headers=headers)

    assert response.status_code == 200
    assert [task["title"] for task in response.get_json()] == ["Newer", "Older"]


def test_update_title_and_status(client):
    headers = auth_headers(client)
    task_id = client.post("/tasks", json={"title": "Original"}, headers=headers).get_json()["id"]

    response = client.put(
        f"/tasks/{task_id}", json={"title": "Updated", "status": "done"}, headers=headers
    )

    assert response.status_code == 200
    assert response.get_json()["title"] == "Updated"
    assert response.get_json()["status"] == "done"


def test_update_single_field_preserves_other_values(client):
    headers = auth_headers(client)
    task = client.post("/tasks", json={"title": "Keep me"}, headers=headers).get_json()

    response = client.put(f"/tasks/{task['id']}", json={"status": "active"}, headers=headers)

    assert response.get_json()["title"] == "Keep me"
    assert response.get_json()["status"] == "active"


@pytest.mark.parametrize("method", ["get", "put"])
def test_missing_task_returns_json_404(client, method):
    kwargs = {"json": {"status": "done"}} if method == "put" else {}
    kwargs["headers"] = auth_headers(client)

    response = getattr(client, method)("/tasks/999", **kwargs)

    assert response.status_code == 404
    assert response.get_json() == {"error": "task not found"}


def test_users_only_see_and_update_their_own_tasks(client):
    alice_headers = auth_headers(client, "alice", "alice-password")
    alice_task = client.post(
        "/tasks", json={"title": "Alice task"}, headers=alice_headers
    ).get_json()
    bob_headers = auth_headers(client, "bob", "bob-password")
    bob_task = client.post("/tasks", json={"title": "Bob task"}, headers=bob_headers).get_json()

    assert client.get("/tasks", headers=alice_headers).get_json() == [alice_task]
    assert client.get("/tasks", headers=bob_headers).get_json() == [bob_task]
    assert client.get(f"/tasks/{alice_task['id']}", headers=bob_headers).status_code == 404
    assert client.put(
        f"/tasks/{alice_task['id']}", json={"status": "done"}, headers=bob_headers
    ).status_code == 404
    assert client.get(f"/tasks/{alice_task['id']}", headers=alice_headers).get_json()["status"] == "pending"

